import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class PredictionSeasonsScreen extends StatelessWidget{PredictionSeasonsScreen({super.key});final repo=FootballRepository();@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Prediction Seasons')),body:FutureBuilder<List<dynamic>>(future:repo.predictionSeasons(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(12),children:s.data!.map((x)=>Card(child:ListTile(leading:const Icon(Icons.emoji_events),title:Text('${x['name']}'),subtitle:Text('${x['starts_at']} → ${x['ends_at']}'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>PredictionSeasonLeaderboardScreen(id:x['id'],name:x['name'])))))).toList());}));}
class PredictionSeasonLeaderboardScreen extends StatelessWidget{const PredictionSeasonLeaderboardScreen({super.key,required this.id,required this.name});final int id;final String name;@override Widget build(BuildContext context){final repo=FootballRepository();return Scaffold(appBar:AppBar(title:Text(name)),body:FutureBuilder<List<dynamic>>(future:repo.predictionSeasonLeaderboard(id),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView.builder(itemCount:s.data!.length,itemBuilder:(c,i){final x=s.data![i];return ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text('${x['user']?['username']??x['user']?['name']??''}'),subtitle:Text('Exact ${x['exact_scores']??0} • Streak ${x['current_streak']??0}'),trailing:Text('${x['points']??0} pts'));});}));}}
